INSERT INTO public.listing_sources (listing_id, source_type, publisher_name, source_url, reference_code, captured_at, notes) VALUES (property_listing_id, 'editorial_import', 'บริษัท บริหารสินทรัพย์สุขุมวิท จำกัด (SAM)', 'https://www.sam.or.th/site/npa/detail.php?id=18891&keyref=6007684', '3A0245', now(), 'Official source captured 2026-09-11. THB 6,750,000; five plots 217 sq.wah; multiple registered homes. Aggregate six bedrooms/six bathrooms; house 12/1 two-bedroom/three-bathroom subset not added again. Access parcel 191390/218 not dedicated public per SAM despite municipal maintenance; disclosed. Twenty-one source images, building photos 2025-02-22. Navigation/map agree. All-status duplicate search no matches.') ;
INSERT INTO public.listing_translations (listing_id, language_code, title, description, address_line1, address_line2, road, subdistrict_name, district_name, province_name, seo_title, seo_description, translation_status, translation_source, reviewed_at, search_text) VALUES (property_listing_id, 'en', 'SAM Direct Sale: Multi-House Property, Prem Chai Rat Soi 3, THB 6.75M', 'Group of residential buildings on five adjoining plots, addresses 10, 12 and 12/1, Prem Chai Rat Soi 3, Mueang subdistrict, Mueang Chon Buri district, Chon Buri. Chanote titles 76921, 85583, 86026, 108997 and 108998 total 217 sq.wah (868 sq.m.). SAM''s summary lists six bedrooms and six bathrooms for the property. Announced total price THB 6,750,000; asset 3A0245, not a per-house price.
